param([ValidateSet('set','clear','show')][string]$Action); . "$PSScriptRoot\lib\Common.ps1"; . "$PSScriptRoot\lib\Network.ps1"; Assert-Administrator; switch($Action){'set'{Set-CPAStackProxy}' 'clear'{Remove-Item (Join-Path (Get-CPAStackRoot) 'config\proxy.psd1') -Force -ErrorAction SilentlyContinue} 'show'{if(Test-Path (Join-Path (Get-CPAStackRoot) 'config\proxy.psd1')){'Proxy is configured.'}else{'No proxy configured.'}}}
